mapper.select:
SELECT COUNT(1) FROM subsidy_apply
WHERE user_id = #{userId}
  AND policy_id = #{policyId}
  AND status IN
#{s}

SELECT COUNT(1) FROM subsidy_apply
WHERE user_id = #{userId}
AND status = #{status}

SELECT , p.title AS policy_title, p.category
FROM subsidy_apply a
LEFT JOIN subsidy_policy p ON p.id = a.policy_id
WHERE a.user_id = #{userId}
AND a.status = #{status}
ORDER BY a.created_at DESC, a.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM subsidy_apply a

    AND a.status <> 'DRAFT'
    AND a.status = #{status}

        AND a.status IN
        #{s}

    AND a.village_code = #{villageCode}
    AND a.town_code = #{townCode}

SELECT ,
       p.title AS policy_title,
       p.category,
       u.name AS applicant_name,
       u.phone AS applicant_phone
FROM subsidy_apply a
LEFT JOIN subsidy_policy p ON p.id = a.policy_id
LEFT JOIN sys_user u ON u.id = a.user_id

    AND a.status <> 'DRAFT'
    AND a.status = #{status}

        AND a.status IN
        #{s}

    AND a.village_code = #{villageCode}
    AND a.town_code = #{townCode}

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{offset}, #{limit}
